import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';
import './EmployeeDashboard.css';

function EmployeeDashboard() {
  const [employee, setEmployee] = useState(null);
  const [transactions, setTransactions] = useState([]);
  const [selectedTransactions, setSelectedTransactions] = useState([]);
  const [filter, setFilter] = useState('pending');
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState({ type: '', text: '' });
  const navigate = useNavigate();

  useEffect(() => {
    const storedEmployee = localStorage.getItem('employee');
    const token = localStorage.getItem('employeeToken');

    if (!storedEmployee || !token) {
      navigate('/employee/login');
      return;
    }

    setEmployee(JSON.parse(storedEmployee));

    // Set token for employee API calls
    api.defaults.headers.common['Authorization'] = `Bearer ${token}`;

    fetchTransactions();
  }, [navigate, filter]);

  const fetchTransactions = async () => {
    try {
      const endpoint = filter === 'pending' 
        ? '/employee/transactions/pending' 
        : '/employee/transactions/all';

      const response = await api.get(endpoint);
      setTransactions(response.data.transactions);
    } catch (err) {
      console.error('Failed to fetch transactions:', err);
      setMessage({ type: 'error', text: 'Failed to load transactions' });
    }
  };

  const handleApprove = async (transactionId) => {
    setLoading(true);
    setMessage({ type: '', text: '' });

    try {
      await api.patch(`/employee/transactions/${transactionId}/verify`);
      setMessage({ type: 'success', text: '✓ Transaction approved successfully!' });

      // Refresh transactions after approval
      setTimeout(() => {
        fetchTransactions();
        setMessage({ type: '', text: '' });
      }, 2000);
    } catch (err) {
      setMessage({ type: 'error', text: err.response?.data?.error || 'Approval failed' });
    } finally {
      setLoading(false);
    }
  };

  const handleSelectTransaction = (transactionId) => {
    setSelectedTransactions(prev => {
      if (prev.includes(transactionId)) {
        return prev.filter(id => id !== transactionId);
      }
      return [...prev, transactionId];
    });
  };

  const handleSubmitToSwift = async () => {
    if (selectedTransactions.length === 0) {
      setMessage({ type: 'error', text: 'Please select at least one verified transaction' });
      return;
    }

    setLoading(true);
    setMessage({ type: '', text: '' });

    try {
      const response = await api.post('/employee/transactions/submit-swift', {
        transactionIds: selectedTransactions
      });

      setMessage({ type: 'success', text: `✓ ${response.data.message}` });
      setSelectedTransactions([]);

      setTimeout(() => {
        fetchTransactions();
        setMessage({ type: '', text: '' });
      }, 2000);
    } catch (err) {
      setMessage({ type: 'error', text: err.response?.data?.error || 'SWIFT submission failed' });
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('employeeToken');
    localStorage.removeItem('employee');
    navigate('/');
  };

  if (!employee) return null;

  const pendingCount = transactions.filter(t => t.status === 'pending').length;
  const verifiedCount = transactions.filter(t => t.status === 'verified').length;
  const submittedCount = transactions.filter(t => t.status === 'submitted').length;

  return (
    <div className="employee-dashboard">
      <nav className="employee-nav">
        <h1>🏦 Employee Portal - Transaction Management</h1>
        <div className="nav-right">
          <span className="employee-info">
            <span className="employee-name">{employee.fullName}</span>
            <span className="employee-role">{employee.role}</span>
          </span>
          <button onClick={handleLogout} className="btn-logout">Logout</button>
        </div>
      </nav>

      <div className="employee-content">
        {/* Statistics Cards */}
        <div className="stats-cards">
          <div className="stat-card pending">
            <div className="stat-icon">⏳</div>
            <div className="stat-info">
              <div className="stat-number">{pendingCount}</div>
              <div className="stat-label">Pending Approval</div>
            </div>
          </div>
          <div className="stat-card verified">
            <div className="stat-icon">✓</div>
            <div className="stat-info">
              <div className="stat-number">{verifiedCount}</div>
              <div className="stat-label">Approved</div>
            </div>
          </div>
          <div className="stat-card submitted">
            <div className="stat-icon">📤</div>
            <div className="stat-info">
              <div className="stat-number">{submittedCount}</div>
              <div className="stat-label">Submitted to SWIFT</div>
            </div>
          </div>
        </div>

        <div className="controls-section">
          <div className="filter-buttons">
            <button 
              className={`filter-btn ${filter === 'pending' ? 'active' : ''}`}
              onClick={() => setFilter('pending')}
            >
              ⏳ Pending ({pendingCount})
            </button>
            <button 
              className={`filter-btn ${filter === 'all' ? 'active' : ''}`}
              onClick={() => setFilter('all')}
            >
              📋 All Transactions ({transactions.length})
            </button>
          </div>

          {verifiedCount > 0 && (
            <div className="swift-section">
              <button 
                onClick={handleSubmitToSwift} 
                disabled={loading || selectedTransactions.length === 0}
                className="btn-swift"
              >
                📤 Submit {selectedTransactions.length || verifiedCount} to SWIFT
              </button>
            </div>
          )}
        </div>

        {message.text && (
          <div className={`message-banner ${message.type}`}>
            {message.text}
          </div>
        )}

        <div className="transactions-grid">
          {transactions.length === 0 ? (
            <div className="no-data">
              <div className="no-data-icon">📭</div>
              <p>No transactions to display</p>
            </div>
          ) : (
            transactions.map((txn) => (
              <div key={txn._id} className={`transaction-card status-${txn.status}`}>
                <div className="card-header">
                  <span className={`status-badge badge-${txn.status}`}>
                    {txn.status === 'pending' && '⏳'}
                    {txn.status === 'verified' && '✓'}
                    {txn.status === 'submitted' && '📤'}
                    {' '}{txn.status.toUpperCase()}
                  </span>
                  <span className="amount">{txn.currency} {txn.amount.toFixed(2)}</span>
                </div>

                <div className="card-body">
                  <div className="info-grid">
                    <div className="info-item">
                      <span className="info-label">Customer</span>
                      <span className="info-value">{txn.userId?.fullName || 'N/A'}</span>
                    </div>
                    <div className="info-item">
                      <span className="info-label">Account</span>
                      <span className="info-value">{txn.userId?.accountNumber || 'N/A'}</span>
                    </div>
                    <div className="info-item">
                      <span className="info-label">Payee Account</span>
                      <span className="info-value">{txn.payeeAccountNumber}</span>
                    </div>
                    <div className="info-item">
                      <span className="info-label">SWIFT Code</span>
                      <span className="info-value swift-code">{txn.swiftCode}</span>
                    </div>
                    <div className="info-item">
                      <span className="info-label">Provider</span>
                      <span className="info-value">{txn.provider}</span>
                    </div>
                    <div className="info-item">
                      <span className="info-label">Date</span>
                      <span className="info-value">{new Date(txn.createdAt).toLocaleString()}</span>
                    </div>
                  </div>
                </div>

                <div className="card-actions">
                  {txn.status === 'pending' && (
                    <button 
                      onClick={() => handleApprove(txn._id)}
                      disabled={loading}
                      className="btn-approve"
                    >
                      ✓ Approve Transaction
                    </button>
                  )}

                  {txn.status === 'verified' && (
                    <label className="checkbox-container">
                      <input
                        type="checkbox"
                        checked={selectedTransactions.includes(txn._id)}
                        onChange={() => handleSelectTransaction(txn._id)}
                      />
                      <span className="checkbox-label">Select for SWIFT Submission</span>
                    </label>
                  )}

                  {txn.status === 'submitted' && (
                    <div className="submitted-badge">
                      <span className="check-icon">✓</span>
                      Submitted to SWIFT Successfully
                    </div>
                  )}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

export default EmployeeDashboard;
